// CACHE_CONTROL NOTE - read before editing the HTTP Request node below.
//
// The HTTP Request node POSTs to the Anthropic Messages API with a
// `system` field that is an ARRAY of content blocks. The FIRST block
// carries "cache_control": {"type": "ephemeral"} - that marks the
// large static prefix (foundation rules, routing policy, the byte-
// identical context every call shares) as a cache breakpoint.
//
// HOW THE WIN WORKS:
//   - Call 1 in a 5-minute window WRITES the cache (1.25x normal input
//     cost for the cached portion).
//   - Calls 2..N within the window READ the cache (~0.10x input cost).
//   - Break-even lands after the 2nd call; clear win from the 3rd on.
//
// HARD REQUIREMENTS:
//   1. The cached block must be BYTE-IDENTICAL across calls. Do not
//      interpolate per-request values into it. Keep dynamic content in
//      the SECOND (non-cached) system block or in the user message.
//   2. The cached block should be >= ~1024 tokens (larger-model floor)
//      or the API will not cache it and the breakpoint is a no-op.
//   3. TLC FIREWALL: never place clinical / counseling / PHI content in
//      ANY block here. That content never leaves the NAS, cache or no
//      cache. This template is for NON-sensitive system prompts only.
//
// This Code node only documents intent and passes data through. Replace
// the static/dynamic placeholders in the HTTP Request node with your
// real values, then delete this node if you prefer a leaner workflow.
const input = $input.first().json || {};
return [{ json: { user_question: input.user_question || 'PLACEHOLDER - the dynamic per-request user message goes here.' } }];

parameters.jsonBody:
={
  "model": "claude-sonnet-4-6",
  "max_tokens": 1024,
  "system": [
    {
      "type": "text",
      "text": "<LARGE STATIC SYSTEM PROMPT - byte-identical across calls, e.g. foundation rules. Must be >= ~1024 tokens or the cache breakpoint is a no-op. NON-clinical content only - the TLC firewall forbids any clinical/counseling/PHI text from ever leaving the NAS, cache or no cache.>",
      "cache_control": { "type": "ephemeral" }
    },
    {
      "type": "text",
      "text": "<DYNAMIC PER-REQUEST CONTEXT - changes every call, so it carries NO cache_control and sits AFTER the cached block.>"
    }
  ],
  "messages": [
    {
      "role": "user",
      "content": "{{ $json.user_question.replace(/\\/g,'\\\\').replace(/\"/g,'\\\"') }}"
    }
  ]
}

parameters.jsCode:
// Extract the text answer and surface the cache usage counters so you
// can confirm the cache is actually being hit. The Anthropic response
// `usage` object reports:
//   cache_creation_input_tokens - tokens WRITTEN to cache (this call)
//   cache_read_input_tokens     - tokens READ from cache (this call)
//   input_tokens                - uncached input tokens this call
//   output_tokens               - generated tokens this call
// A healthy cached call shows cache_read_input_tokens > 0 and a small
// input_tokens. The first call in a window shows cache_creation > 0.
const raw = $input.first().json || {};
let answer = '';
try {
  const blocks = raw.content || [];
  answer = blocks.map(function (b) { return b.text || ''; }).join('').trim();
} catch (e) { answer = ''; }
const usage = raw.usage || {};
return [{
  json: {
    ok: !!answer,
    answer: answer,
    model: raw.model || 'claude-sonnet-4-6',
    cache_creation_input_tokens: usage.cache_creation_input_tokens || 0,
    cache_read_input_tokens: usage.cache_read_input_tokens || 0,
    input_tokens: usage.input_tokens || 0,
    output_tokens: usage.output_tokens || 0
  }
}];
